"""Real UX controls in a disposable profile, with synthetic local data only."""
import json


def run_prerelease_ux_checks(*, cdp, e, check, wait_for, load, add, shot):
    q = json.dumps
    def frame():
        e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
    def viewport(width, height, touch=False):
        cdp.call('Emulation.setDeviceMetricsOverride', width=width, height=height, deviceScaleFactor=1, mobile=touch)
        cdp.call('Emulation.setTouchEmulationEnabled', enabled=touch, maxTouchPoints=5)
        frame()
    def click(selector):
        e(f'document.querySelector({q(selector)}).scrollIntoView({{block:"nearest"}})');frame()
        point=e(f'(()=>{{const r=document.querySelector({q(selector)}).getBoundingClientRect();return {{x:r.x+r.width/2,y:r.y+r.height/2}}}})()')
        cdp.call('Input.dispatchMouseEvent', type='mousePressed', button='left', clickCount=1, **point)
        cdp.call('Input.dispatchMouseEvent', type='mouseReleased', button='left', clickCount=1, **point)
        frame()
    def labels():
        return e("[...addMenu.querySelectorAll('button:not([hidden])')].map(b=>b.textContent)")
    def states():
        return e("['universe-toggle','tasks-toggle','constellations-toggle'].map(id=>document.getElementById(id).getAttribute('aria-expanded'))")
    viewport(1440,1000)
    check(e('entries.size===0&&!firstUse.root.hidden'), 'fresh launch preserves Introduction')
    check(e('getComputedStyle(firstUse.root.querySelector(".first-use-card")).gridTemplateColumns.split(" ").length===2'), 'desktop Introduction keeps two columns')
    shot('ux-introduction-desktop')
    check(e('!tasksView.root.hidden&&!tasksView.empty.hidden&&tasksView.empty.textContent==="No tasks yet."'), 'empty Tasks remains a visible top-level section')
    viewport(390,844,True);e('hierarchySidebar.setCollapsed(false)');frame()
    click('#tasks-toggle')
    check(states()==['false','true','false'] and e('!tasksView.empty.hidden&&!tasksView.view.hidden'), 'empty mobile Tasks participates in the exclusive accordion')
    click('#universe-toggle')
    check(states()==['true','false','false'] and e('document.getElementById("add-entry-button").getClientRects().length>0'), 'empty Universe retains section + and accordion')
    viewport(1440,1000);e('hierarchySidebar.setCollapsed(false)');frame()
    click('#first-use-create')
    check(e('dialog.open&&document.querySelector("label[for=galaxy-starter]").textContent==="Choose a starting point"&&galaxyStarter.options[0].text==="Blank"'), 'New Galaxy clearly offers existing starting points and Blank')
    e('fields[0].value="First project";form.requestSubmit();applicationCommandTail')
    wait_for('!formSaveBusy&&!dialog.open');frame()
    root=e('selectedNode.dataset.entryId')
    wait_for('!firstUse.hint.hidden&&firstUse.hint.style.visibility==="visible"')
    check(e('firstUse.hint.dataset.anchor==="entry-add-button"&&firstUse.hint.textContent.includes("First project")'), 'desktop coach names the created Item and anchors to its +')
    check(e('(()=>{const h=firstUse.hint.getBoundingClientRect(),b=document.getElementById("entry-add-button").getBoundingClientRect(),p=panel.getBoundingClientRect();return h.right<b.left&&h.right<=p.left&&Math.abs(h.top-b.top)<50})()'), 'desktop coach sits beside Contents without covering its controls')
    shot('ux-coach-desktop')
    e('closeInspector()');frame()
    check(e('firstUse.hint.dataset.anchor==="sidebar-add"&&getComputedStyle(firstUse.coachAnchor).opacity==="1"&&getComputedStyle(firstUse.coachAnchor).pointerEvents==="auto"'), 'closing desktop Contents anchors coach to a visible usable sidebar + without hover')
    e('setInspectorOpen(true)');frame()
    viewport(390,844,True)
    wait_for('hierarchySidebar.narrow');frame()
    check(e('firstUse.hint.dataset.anchor==="entry-add-button"'), 'phone expanded Contents coach follows its visible +')
    e('closeInspector()');frame()
    check(e('firstUse.hint.dataset.anchor==="mobile-body-add"&&firstUse.hint.style.visibility==="visible"'), 'phone compact Contents coach follows its visible +')
    check(e('(()=>{const h=firstUse.hint.getBoundingClientRect(),b=document.getElementById("mobile-body-add").getBoundingClientRect();return h.bottom<b.top&&h.left>=0&&h.right<=innerWidth&&b.top-h.bottom<30})()'), 'phone coach points closely above the + within the viewport')
    shot('ux-coach-phone')
    click('#first-use-hint button')
    check(e('firstUse.hint.hidden&&firstUse.coachFrame===null&&firstUse.timer===null&&!document.querySelector(".first-use-add-target")'), 'dismissal clears coach target, layout and timeout')
    e('applicationCommandTail');e('window.uxDismissReload=true');cdp.call('Page.reload')
    wait_for('typeof uxDismissReload==="undefined"&&document.readyState==="complete"&&typeof firstUse!=="undefined"');load();frame()
    check(e('firstUse.state.phase==="child"&&firstUse.hint.hidden'), 'dismissed first-Item coach does not restart on reload before a child exists')
    child=add('Nested item',root)
    e('firstUse.hideHint()')
    task_list=e(f'(async()=>{{createChildEntry({q(root)},true);fields[0].value="Project tasks";document.getElementById("task-list-tasks").value="One task";form.requestSubmit();await applicationCommandTail;return selectedNode.dataset.entryId}})()')
    wait_for('!formSaveBusy&&!dialog.open')
    e(f'hierarchySidebar.expanded.add({q(root)});hierarchySidebar.render();hierarchySidebar.setCollapsed(false)');frame()
    before=e('JSON.stringify(persistence.preferences.load())')
    for selector,expected in [('#tasks-toggle',['false','true','false']),('#constellations-toggle',['false','false','true']),('#universe-home',['true','false','false'])]:
        click(selector)
        check(states()==expected, 'phone major section accordion: '+selector)
    check(e(f'hierarchySidebar.expanded.has({q(root)})'), 'major sections retain nested Universe branches')
    check(e('JSON.stringify(persistence.preferences.load())')==before, 'mobile accordion does not overwrite desktop disclosure preferences')
    click('#constellations-toggle')
    check(e('constellations.size===0&&constellationWorkspace.list.textContent.includes("Connect related items from anywhere in your Universe.")&&constellationWorkspace.list.querySelector("button").getClientRects().length>0'), 'zero Constellations explain the concept and offer creation')
    shot('ux-empty-constellations-phone')
    e(f'openContextMenu({q(root)},50,100)')
    check(e('contextMenu.querySelector("[data-action=constellation]").hidden'), 'zero Constellations hide shared Item membership action')
    e('closeContextMenu()')
    click('#universe-toggle')
    check(e('[...hierarchySidebar.tree.querySelectorAll(".tree-add")].every(b=>b.hidden&&b.getClientRects().length===0)&&[...hierarchySidebar.tree.querySelectorAll(".tree-more")].every(b=>b.getClientRects().length>0)'), 'mobile sidebar hides row + and preserves management')
    row=f'.hierarchy-row[data-entry-id="{root}"]'
    click(row+' .tree-more')
    check(e(f'!contextMenu.hidden&&contextEntryId==={q(root)}&&!contextMenu.querySelector("[data-action=edit]").hidden&&!contextMenu.querySelector("[data-action=duplicate-structure]").hidden'), 'mobile row management remains directly usable')
    e('closeContextMenu()')
    click('#add-entry-button')
    check(e('dialog.open&&!creatingTaskList'), 'mobile Universe + still opens New Galaxy')
    click('#cancel-add-entry')
    e(f'selectEntry(entries.get({q(root)}),nodes.get({q(root)}),{{openInspector:false,reframe:false}});hierarchySidebar.setCollapsed(true)');frame()
    click('#mobile-body-add')
    expected=['Take a photo','Add photo','Add files','Add item','Add task list']
    check(labels()==expected, 'mobile Preview Contents + contains the five supported actions')
    check(e('!addMenu.textContent.includes("Take Photo")&&!addMenu.textContent.includes("Photo Gallery")&&!addMenu.textContent.includes("Add photo or file")'), 'unified and duplicate source choices are absent')
    shot('ux-preview-add-phone')
    e('window.uxPicker=[];[contentInspector.files,contentInspector.photoFiles,contentInspector.cameraFiles].forEach(input=>input.click=function(){uxPicker.push({capture:this.getAttribute("capture"),accept:this.getAttribute("accept"),multiple:this.multiple})})')
    before_photo=e('localStorage.getItem("galaxy:user-data")')
    click('#add-menu [data-add=photo]')
    check(e('uxPicker.length===1&&uxPicker[0].capture===null&&uxPicker[0].accept==="image/*"&&uxPicker[0].multiple'), 'Add photo requests image sources including HEIF without forcing a camera')
    e('(contentInspector.fileSelection?.input||contentInspector.files).dispatchEvent(new Event("cancel"))')
    check(e('contentInspector.fileSelection===null') and e('localStorage.getItem("galaxy:user-data")')==before_photo, 'photo cancellation preserves metadata and clears its destination')
    e(f'selectEntry(entries.get({q(root)}),nodes.get({q(root)}),{{openInspector:false,reframe:false}});hierarchySidebar.setCollapsed(true)');frame()
    click('#mobile-body-add')
    click('#add-menu [data-add=capture-files]')
    check(e('uxPicker.length===2&&uxPicker[1].capture===null&&uxPicker[1].accept===null&&uxPicker[1].multiple'), 'Add file clears the photo restriction and requests generic files')
    check(e(f'contentInspector.fileSelection.entryId==={q(root)}'), 'native picker retains exact selected destination')
    e('(contentInspector.fileSelection?.input||contentInspector.files).dispatchEvent(new Event("cancel"))')
    e(f'selectEntry(entries.get({q(root)}),nodes.get({q(root)}),{{openInspector:false,reframe:false}});hierarchySidebar.setCollapsed(true)');frame()
    click('#mobile-body-add')
    click('#add-menu [data-add=camera]')
    check(e('uxPicker.length===3&&uxPicker[2].capture==="environment"&&uxPicker[2].accept==="image/*"&&!uxPicker[2].multiple&&contentInspector.fileSelection.input===contentInspector.cameraFiles'), 'Take a photo uses its own single rear-camera input')
    e('contentInspector.photoFiles.dispatchEvent(new Event("cancel"))')
    check(e('contentInspector.fileSelection.input===contentInspector.cameraFiles&&!document.getElementById("content-file-limit").hidden'), 'late cancellation from the photo input leaves the camera destination intact')
    e('contentInspector.cameraFiles.dispatchEvent(new Event("cancel"))')
    check(e('contentInspector.fileSelection===null&&document.getElementById("content-file-limit").hidden'), 'camera cancellation clears only its own selection')
    for page,control,condition in [('notes','content-browse-add-note','!contentInspector.notesForm.hidden'),('links','content-add-bookmark','!contentInspector.quickBookmark.hidden'),('location','content-add-location','!document.getElementById("content-location-form").hidden')]:
        e(f'setInspectorOpen(true);mobileContents.setPage({q(page)})');frame()
        click('#'+control)
        check(e(f'!panel.hidden&&contentInspector.entryId==={q(root)}&&{condition}'), 'direct content section opens existing '+page+' editor')
        e('document.querySelectorAll("#entry-panel .inline-editor:not([hidden])").forEach(form=>form.querySelector("button[type=button]")?.click())')
    e(f'selectEntry(entries.get({q(root)}),nodes.get({q(root)}),{{openInspector:true,reframe:false}});hierarchySidebar.setCollapsed(true)');frame()
    click('#entry-add-button')
    check(labels()==expected[:5], 'Contents + remains compact with camera, photo, files, Item and Task List only')
    e('closeContentMenus();hierarchySidebar.setCollapsed(false)');frame()
    click('#constellations-toggle')
    click('.constellation-empty button')
    check(e('constellationWorkspace.nameDialog.open'), 'empty-state create action opens existing Constellation dialog')
    e('document.getElementById("constellation-name").value="Related work";constellationWorkspace.saveName()')
    wait_for('constellations.size===1&&!constellationWorkspace.nameDialog.open');frame()
    e(f'openContextMenu({q(root)},50,100)')
    check(e('!contextMenu.querySelector("[data-action=constellation]").hidden'), 'membership action becomes available after first Constellation')
    e('contextMenu.querySelector("[data-action=constellation]").click()')
    check(e('!document.getElementById("constellation-memberships").hidden'), 'existing membership picker still opens')
    e('closeContextMenu()')
    for width,height,touch in [(1440,1000,False),(900,1000,True),(360,800,True),(390,844,True),(430,932,True),(844,390,True)]:
        viewport(width,height,touch)
        mobile=width<=760 or (touch and width<=1024 and height<=500)
        check(e('hierarchySidebar.narrow')==mobile, f'{width}x{height}: existing mobile breakpoint retained')
        e('closeContentMenus();closeContextMenu();closeInspector();hierarchySidebar.setCollapsed(false)');frame()
        if not mobile:
            e('hierarchySidebar.universeSection.setCollapsed(false);tasksView.section.setCollapsed(false);constellationWorkspace.section.setCollapsed(false)');frame()
            check(states()==['true','true','true'], f'{width}: wide sections coexist')
            click('#tasks-toggle')
            check(states()==['true','false','true'], f'{width}: wide Tasks disclosure is independent')
            click('#tasks-toggle')
        else:
            click('#universe-toggle')
            check(states()==['true','false','false'], f'{width}: phone accordion remains exclusive')
        cdp.call('Input.dispatchMouseEvent',type='mouseMoved',x=500,y=60)
        check(e('(()=>{const a=getComputedStyle(document.querySelector("#tasks-toggle span")),b=getComputedStyle(document.querySelector("#constellations-toggle span"));return ["fontSize","fontWeight","color","textTransform"].every(k=>a[k]===b[k])})()'), f'{width}: Tasks and Constellations have equal visual prominence')
        click('#utility-more')
        check(e('document.getElementById("utility-more").ariaLabel==="More"&&!document.getElementById("utility-menu").hidden'), f'{width}: accessible More opens')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='ArrowDown',code='ArrowDown',windowsVirtualKeyCode=40)
        check(e('document.activeElement.id==="backup-button"'), f'{width}: More supports keyboard menu navigation')
        check(e('(()=>{const r=document.getElementById("utility-menu").getBoundingClientRect(),b=document.getElementById("utility-more").getBoundingClientRect();return r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight&&(r.bottom<=b.top||r.top>=b.bottom)})()'), f'{width}: utility menu fits viewport and leaves its trigger uncovered')
        check(e('(()=>{const a=getComputedStyle(document.getElementById("utility-menu")),b=getComputedStyle(contextMenu);return ["width","backgroundColor","borderColor","borderWidth","borderRadius","boxShadow","padding"].every(k=>a[k]===b[k])})()'), f'{width}: More reuses the contextual menu surface')
        check(e('(()=>{const a=getComputedStyle(document.getElementById("help-button")),b=getComputedStyle(contextMenu.querySelector("[data-action=edit]"));return ["fontSize","fontFamily","fontWeight","lineHeight","padding","borderRadius","minHeight","color"].every(k=>a[k]===b[k])})()'), f'{width}: More reuses contextual menu row typography, spacing and touch sizing')
        shot(f'ux-more-{width}')
        for button,dialog in [('help-button','help-dialog'),('backup-button','backup-dialog'),('account-button','account-dialog')]:
            if e('document.getElementById("utility-menu").hidden'):click('#utility-more')
            click('#'+button)
            check(e(f'document.getElementById({q(dialog)}).open&&document.getElementById("utility-menu").hidden'), f'{width}: More opens '+button)
            # Native close exercises the normal dialog close/focus listeners.
            e(f'document.getElementById({q(dialog)}).close()');frame()
            check(e('document.activeElement.id==="utility-more"'), f'{width}: utility dialog restores More focus')
        click('#utility-more')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        frame()
        check(e('document.getElementById("utility-menu").hidden&&document.activeElement.id==="utility-more"&&!hierarchySidebar.collapsed'), f'{width}: Escape dismisses only More')
    e('window.uxReloadMarker=true');cdp.call('Page.reload')
    wait_for('typeof uxReloadMarker==="undefined"&&document.readyState==="complete"&&typeof firstUse!=="undefined"');load();frame()
    check(e('firstUse.hint.hidden&&firstUse.state.phase==="done"&&entries.size>1&&constellations.size===1'), 'existing saved data reloads without recurring onboarding or migration')
    check(e('document.querySelector(".brand-mark").getAttribute("aria-hidden")==="true"&&!document.querySelector(".brand-mark").closest("button,a")'), 'helmet branding is decorative and noninteractive')
    check(e('(()=>{const brand=document.querySelector(".brand-mark"),more=document.querySelector("#utility-more svg");return !!brand.querySelector("rect")&&!!more.querySelector("circle")&&brand.innerHTML!==more.innerHTML&&document.getElementById("utility-more").ariaLabel==="More"})()'), 'helmet identity and interactive rocket More use distinct artwork')
    check(not cdp.errors, 'no prerelease UX browser exceptions: '+q(cdp.errors))
